Ltac c8cb H k :=
  lazymatch type of H with rw_cells _ ?m ?A ?cs =>
    let pre := eval cbv beta iota delta [firstn] in (firstn k cs) in
    let post := eval cbv beta iota delta [skipn] in (skipn (S k) cs) in
    lazymatch eval cbv beta iota delta [nth_error] in (nth_error cs k) with Some (C8 ?v) =>
      let H' := fresh in pose proof (rw_cells_C8_CB m A pre v post H) as H'; cbn [app] in H'; clear H; rename H' into H
    end end.
Lemma lor40 : forall x, Z.land (Z.lor 40 x) 15 = 0 -> False.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S:0!1,B|508;!1,B|37;!2'^60#2|11;!1,B3!2'^:24!2'^:14!2'^:04!2'^:!2'^5214!2'^:,^74$x;R+0$E;R!3+<+0!2'^5!2'^60#11,^7&T;R!6'>+^8!2'^956$b;R+^8!3+<+^8#1,^;!6'>+^8!2'^<7!2'^:#24$b;R+^8!3+<+^8!2'^9#16,^;&H;R!2,9+^87!3+<+^8,^;7!6'T+^8,^;$b;R+^8!3+<+^8!2'^9!2'^<#1!2'^:#446,^;!2,9+^8,^;7#15!3'^=0#248!3'^>214!3+<+^88,^;&T;R!6'T+0!2'^5!2'^60#31$z;R+0!3+<+^8!2'^:#14,^;#1,^7#2!3+<+^89,^;&H;R!6'T+^89$e;R+^8-^8RN$b;R+^8w#12+^?+^@,^A,^;#1+^?!2'^B+^?#1").
Qed.

Section PR.
Variables ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word.
Variables (F : bvmap 5 word) (fc : bv 32) (m : word -> option byte) (A VA lo : Z).
Hypothesis HA0 : 65536 <= A.
Hypothesis HA : A + 6 <= 1441856.
Hypothesis LO : lo <= bv_unsigned sp - 2400.
Hypothesis HLO : 17594333495296 <= lo.
Hypothesis HQ : bv_unsigned sp <= 140737488355072.
Definition FMTB : list byte := ltac2:(Rpl.RP.run_i (rplG ()) 0 "S20!1,4|30;!1+30!3,51!2'60!1,B|505;!3,51!2'60!1,B|511;!3,51!2'60!1,B|50e;!3,51!2'60!1,B|50a;!3,51!2'60!1,B|627;!3,51!2'60,^7!1,81").
Definition SAVES : list cell := ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00!3,5+I!1,Y/s11;!3,5+I!1,Y/s10;!3,5+I!1,Y/s9;!3,5+I!1,Y/s8;!3,5+I!1,Y/s7;!3,5+I!1,Y/s6;!3,5+I!1,Y/s5;!3,5+I!1,Y/s4;!3,5+I!1,Y/s3;!3,5+I!1,Y/s2;!3,5+I!1,Y/s1;!3,5+I!1,Y/s0;!3,5+I!1,Y/ra;!1,8+I").

Ltac zb := zstep; try fix_le1; try (fix_litstore; mem_after_store_opt);
  try lazymatch goal with
  | |- evt _ _ (MS _ _ (if ?c then _ else _) _ _ _ _) =>
      lazymatch c with
      | context [sp] => let Kz := fresh "Kz" in if_cases Kz; zify_cond Kz; try (exfalso; first [lia | exact (lor40 _ Kz)]); try clear Kz
      | _ => lit_branch
      end
  end.
Local Notation POST := (pcom_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc lo m).

Lemma pr1 : forall (rav t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 ctx t3 t4 t5 t6 : word) (m0 : word -> option byte),
  stk rsegs m0 lo (bv_unsigned sp + -104) -> rw_cells rsegs m0 (bv_unsigned sp + -104) SAVES ->
  ro_cells rsegs m0 A [CB 6 FMTB] -> munch [(lo, bv_unsigned sp)] m m0 -> wmono rsegs m m0 -> mem_inv rsegs m0 ->
  evt rsegs POST (MS (mkR rav (Z_to_bv 64 (bv_unsigned sp + -2240)) gp tp t0 t1 t2 sp s1 a0 a1 a2 a3 a4 a5 a6 a7
